import { apiClient } from "@/lib/apiClient";

export default async function sendMessage({ data }: { data: any }) {
  // apiv3 B2C: POST /representatives/ask-question (recaptcha korumalı).
  // Tarayıcıdan çağrılır → apiClient /api/apiv3 proxy'sine gider, token sunucuda eklenir.
  // Hata (422 recaptcha/validasyon) durumunda apiClient ApiError fırlatır.
  return apiClient("/representatives/ask-question", {
    method: "POST",
    body: data,
  });
}
