import { useEffect, useState } from "react";
import { getCookie, hasCookie } from "cookies-next";
import getUserDetail from "@/services/auth/userDetail";
import sendMessage from "@/services/askRepresentativeQuestionService";
import ReCAPTCHA from "react-google-recaptcha";
import { inputCls, labelCls } from "@/components/profile-page/fieldStyles";

export default function InquiryModal({
  representative,
  open,
  onClose,
}: {
  representative: any;
  open: boolean;
  onClose: () => void;
}) {
  const [loading, setLoading] = useState(true);
  const [messageSendLoading, setMessageSendLoading] = useState(false);
  const [isActiveUser, setIsActiveUser] = useState(false);
  const [customerName, setCustomerName] = useState("");
  const [customerPhone, setCustomerPhone] = useState("");
  const [customerEmail, setCustomerEmail] = useState("");
  const [googleRecaptcha, setGoogleRecaptcha] = useState<any>(null);
  const [question, setQuestion] = useState("");
  const [showError, setShowError] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [bodyContent, setBodyContent] = useState("form");

  const fetchUserDetail = async () => {
    const userData = await getUserDetail({ token: getCookie("auth-token") });
    return userData;
  };

  const formSubmit = () => {
    if (customerName == "" || customerEmail == "" || question == "") {
      setShowError(true);
      setErrorMessage("Please fill in the required fields.");
      return;
    }

    if (!googleRecaptcha) {
      setShowError(true);
      setErrorMessage("Please confirm robot verification.");
      return;
    }

    setShowError(false);
    setErrorMessage("");
    setMessageSendLoading(true);

    sendMessage({
      data: {
        representative_id: representative.id,
        name: customerName,
        phone: customerPhone,
        email: customerEmail,
        "g-recaptcha-response": googleRecaptcha,
        message: question,
      },
    })
      .then((res) => {
        setMessageSendLoading(false);
        setBodyContent("success");
      })
      .catch((error) => {
        setMessageSendLoading(false);
        setErrorMessage("There is a problem. Please try again later.");
        setShowError(true);
      });
  };

  useEffect(() => {
    if (hasCookie("auth-token")) {
      fetchUserDetail().then((res: any) => {
        setIsActiveUser(true);
        setCustomerName(res.name);
        setCustomerPhone(res.phone);
        setCustomerEmail(res.email);
        setLoading(false);
      });
    } else {
      setLoading(false);
    }
  }, []);

  if (!open) return null;

  return (
    <div
      className="tw-fixed tw-inset-0 tw-z-[1050] tw-flex tw-items-center tw-justify-center tw-bg-black/50 tw-p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="inquiryFormLabel"
      onClick={() => {
        if (!messageSendLoading) onClose();
      }}
    >
      <div
        className="tw-flex tw-max-h-[90vh] tw-w-full tw-max-w-lg tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-shadow-[0_20px_60px_rgba(20,16,28,0.3)]"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="tw-flex tw-items-center tw-justify-between tw-gap-3 tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] tw-px-5 tw-py-4">
          <span
            className="tw-font-display tw-text-lg tw-font-bold tw-text-[#14101c]"
            id="inquiryFormLabel"
          >
            Ask a Question
          </span>
          {!messageSendLoading && (
            <button
              type="button"
              className="tw-flex tw-h-8 tw-w-8 tw-shrink-0 tw-cursor-pointer tw-items-center tw-justify-center tw-rounded-full tw-border-0 tw-bg-[#f6f4fa] tw-text-lg tw-leading-none tw-text-[#5d556c] tw-transition hover:tw-bg-[#ece9f1]"
              aria-label="Close"
              onClick={onClose}
            >
              ×
            </button>
          )}
        </div>

        <div className="tw-overflow-y-auto tw-px-5 tw-py-4">
          {loading && (
            <p className="tw-m-0 tw-text-sm tw-text-[#5d556c]">Loading...</p>
          )}
          {!loading &&
            !messageSendLoading &&
            bodyContent == "success" && (
              <p className="tw-m-0 tw-text-sm tw-text-[#5d556c]">
                Your message has been delivered successfully. We will get back to
                you as soon as possible.
              </p>
            )}
          {!loading && !messageSendLoading && bodyContent == "form" && (
            <>
              <p className="tw-mt-0 tw-mb-4 tw-text-sm tw-text-[#5d556c]">
                Ask questions to the representative:{" "}
                <strong className="tw-text-[#14101c]">
                  {representative?.name}
                </strong>
              </p>
              {showError && (
                <div
                  className="tw-mb-3 tw-rounded-xl tw-border-0 tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-sm tw-font-medium tw-text-[#b3261e]"
                  role="alert"
                >
                  {errorMessage}
                </div>
              )}
              {!isActiveUser && (
                <>
                  <div className="tw-mb-3">
                    <label htmlFor="inquiryFormName" className={labelCls}>
                      Name <span className="tw-text-[#d6336c]">(*)</span>
                    </label>
                    <input
                      type="text"
                      className={inputCls}
                      id="inquiryFormName"
                      onChange={(e) => {
                        setCustomerName(e.target.value);
                      }}
                      defaultValue={customerName}
                    />
                  </div>
                  <div className="tw-mb-3">
                    <label htmlFor="inquiryFormEmail" className={labelCls}>
                      Email address{" "}
                      <span className="tw-text-[#d6336c]">(*)</span>
                    </label>
                    <input
                      type="email"
                      className={inputCls}
                      id="inquiryFormEmail"
                      onChange={(e) => {
                        setCustomerEmail(e.target.value);
                      }}
                      defaultValue={customerEmail}
                    />
                  </div>
                  <div className="tw-mb-3">
                    <label htmlFor="inquiryFormPhone" className={labelCls}>
                      Phone{" "}
                      <span className="tw-font-normal tw-text-[#8b8397]">
                        (Optional)
                      </span>
                    </label>
                    <input
                      type="text"
                      className={inputCls}
                      placeholder="e.g. +1 234 5678"
                      id="inquiryFormPhone"
                      onChange={(e) => {
                        setCustomerPhone(e.target.value);
                      }}
                      defaultValue={customerPhone}
                    />
                  </div>
                </>
              )}
              <div className="tw-mb-3">
                <label htmlFor="inquiryFormEmailQuestion" className={labelCls}>
                  Your Question <span className="tw-text-[#d6336c]">(*)</span>
                </label>
                <textarea
                  className={`${inputCls} tw-min-h-[120px] tw-resize-y`}
                  id="inquiryFormEmailQuestion"
                  rows={5}
                  onChange={(e) => {
                    setQuestion(e.target.value);
                  }}
                  defaultValue={question}
                ></textarea>
              </div>
              <div className="tw-mb-1">
                <ReCAPTCHA
                  sitekey="6LesOOIpAAAAAE1l4Z8q_ZVqpAGTnNaTRJTDzYxu"
                  onChange={(e) => {
                    setGoogleRecaptcha(e);
                  }}
                  asyncScriptOnLoad={() => {
                    setGoogleRecaptcha(null);
                  }}
                  hl="en"
                />
              </div>
            </>
          )}
          {messageSendLoading && (
            <div className="tw-py-4 tw-text-center">
              <span className="tw-mx-auto tw-mb-3 tw-inline-block tw-h-10 tw-w-10 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#ece9f1] tw-border-t-[#854ec9]" />
              <p className="tw-m-0 tw-text-sm tw-text-[#5d556c]">
                Your message is being sent. Please wait.
              </p>
            </div>
          )}
        </div>

        <div className="tw-flex tw-justify-end tw-gap-2 tw-border-0 tw-border-t tw-border-solid tw-border-[#ece9f1] tw-px-5 tw-py-4">
          {messageSendLoading ? (
            <button
              className="tw-flex tw-cursor-not-allowed tw-items-center tw-gap-2 tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-6 tw-py-2.5 tw-text-sm tw-font-semibold tw-text-white tw-opacity-70"
              type="button"
              disabled
            >
              <span className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent" />
              Sending...
            </button>
          ) : (
            <>
              <button
                type="button"
                className="tw-cursor-pointer tw-rounded-full tw-border tw-border-solid tw-border-[#d6d2de] tw-bg-white tw-px-6 tw-py-2.5 tw-text-sm tw-font-semibold tw-text-[#5d556c] tw-transition hover:tw-bg-[#f6f4fa]"
                onClick={onClose}
              >
                Close
              </button>
              {bodyContent == "form" && (
                <button
                  type="button"
                  className="tw-cursor-pointer tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-6 tw-py-2.5 tw-text-sm tw-font-semibold tw-text-white tw-transition hover:tw-bg-[#6a3da4]"
                  onClick={() => {
                    formSubmit();
                  }}
                >
                  Send Message
                </button>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}
