"use client";
import * as Sentry from "@sentry/nextjs";
import Image from "next/image";
import { useEffect, useState } from "react";
import InquiryModal from "./inquiry-modal";
import Breadcrumb from "@/components/header/breadcrumb";
import { apiClient } from "@/lib/apiClient";

type Representative = {
  id: number;
  name: string;
  email: string | null;
  phone: string | null;
  area_name: string | null;
  country: {
    id: number;
    name: string;
    code: string;
  } | null;
  sort_order: number;
  instagram_url: string | null;
  image: string | null;
  updated_at: string;
  created_at: string;
};

export default function ListPage() {
  const [loading, setLoading] = useState(true);
  const [representatives, setRepresentatives] = useState<Representative[]>([]);
  const [representativeModal, setRepresentativeModal] =
    useState<Representative>();
  const [contactOpen, setContactOpen] = useState(false);
  const [inquiryOpen, setInquiryOpen] = useState(false);

  useEffect(() => {
    const fetchRepresentatives = async () => {
      try {
        const { data } = await apiClient<{ data: Representative[] }>(
          "/representatives"
        );
        setRepresentatives(data);
      } catch (error) {
        Sentry.captureException(error);
      } finally {
        setLoading(false);
      }
    };

    fetchRepresentatives();
  }, []);

  if (loading)
    return (
      <main>
        <div className="tw-mx-auto tw-max-w-screen-xl tw-px-4 tw-my-8">
          <Breadcrumb
            items={[
              { pageTitle: "Representatives", pageUrl: "/representative" },
            ]}
          />
          <h1 className="tw-font-display tw-text-2xl tw-font-bold tw-text-[#14101c]">
            Our Representatives
          </h1>
          <div className="tw-py-16 tw-text-center">
            <span className="tw-mx-auto tw-mb-5 tw-inline-block tw-h-16 tw-w-16 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#ece9f1] tw-border-t-[#854ec9]" />
            <p className="tw-m-0 tw-text-base tw-font-semibold tw-text-[#14101c]">
              Please wait...
            </p>
          </div>
        </div>
      </main>
    );

  return (
    <main>
      <div className="tw-mx-auto tw-max-w-screen-xl tw-px-4 tw-my-8">
        <Breadcrumb
          items={[{ pageTitle: "Representatives", pageUrl: "/representative" }]}
        />
        <h1 className="tw-font-display tw-text-2xl tw-font-bold tw-text-[#14101c]">
          Our Representatives
        </h1>

        <div className="tw-mt-8 tw-grid tw-grid-cols-2 tw-gap-5 md:tw-grid-cols-3 lg:tw-grid-cols-4">
          {representatives.map((rep) => (
            <div
              key={rep.id}
              className="tw-flex tw-flex-col tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-5 tw-text-center tw-shadow-[0_10px_28px_rgba(20,16,28,0.05)] tw-transition-all tw-duration-300 hover:tw--translate-y-1 hover:tw-shadow-[0_14px_34px_rgba(20,16,28,0.12)]"
            >
              <div className="tw-mb-3 tw-flex tw-justify-center">
                {rep.image ? (
                  <Image
                    src={rep.image.replace(
                      "tsgroup.s3.amazonaws.com",
                      "d2lpxiu1sq3srq.cloudfront.net"
                    )}
                    alt={rep.name}
                    width={200}
                    height={200}
                    className="tw-h-[140px] tw-w-[140px] tw-rounded-full tw-object-cover"
                  />
                ) : (
                  <div className="tw-h-[140px] tw-w-[140px] tw-rounded-full tw-bg-[#ece9f1]" />
                )}
              </div>
              <h2 className="tw-font-display tw-text-base tw-font-bold tw-text-[#14101c]">
                {rep.name}
              </h2>
              <p className="tw-mb-4 tw-mt-1 tw-flex tw-items-center tw-justify-center tw-gap-1.5 tw-text-sm tw-text-[#5d556c]">
                {rep.country && (
                  <Image
                    src={
                      "/images/flags/4x3/" +
                      rep.country?.code?.toLowerCase() +
                      ".svg"
                    }
                    alt=""
                    width={20}
                    height={20}
                  />
                )}
                {rep.area_name || ""}
              </p>
              <div className="tw-mt-auto tw-flex tw-flex-wrap tw-gap-2">
                <button
                  type="button"
                  className="tw-flex-1 tw-cursor-pointer tw-rounded-full tw-border tw-border-solid tw-border-[#854ec9] tw-bg-white tw-px-3 tw-py-2 tw-text-sm tw-font-semibold tw-text-[#854ec9] tw-transition hover:tw-bg-[#854ec9]/5"
                  onClick={() => {
                    setRepresentativeModal(rep);
                    setContactOpen(true);
                  }}
                >
                  Contact
                </button>
                <button
                  type="button"
                  className="tw-flex-1 tw-cursor-pointer tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-3 tw-py-2 tw-text-sm tw-font-semibold tw-text-white tw-transition hover:tw-bg-[#6a3da4]"
                  onClick={() => {
                    setRepresentativeModal(rep);
                    setInquiryOpen(true);
                  }}
                >
                  Ask a Question
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* Contact modal */}
        {contactOpen && representativeModal && (
          <div
            className="tw-fixed tw-inset-0 tw-z-[1050] tw-flex tw-items-center tw-justify-center tw-bg-black/50 tw-p-4"
            role="dialog"
            aria-modal="true"
            onClick={() => setContactOpen(false)}
          >
            <div
              className="tw-w-full tw-max-w-md tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-shadow-[0_20px_60px_rgba(20,16,28,0.3)]"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="tw-flex tw-items-center tw-justify-between tw-gap-3 tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] tw-px-5 tw-py-4">
                <span className="tw-font-display tw-text-lg tw-font-bold tw-text-[#14101c]">
                  Representative Contact Infos
                </span>
                <button
                  type="button"
                  className="tw-flex tw-h-8 tw-w-8 tw-shrink-0 tw-cursor-pointer tw-items-center tw-justify-center tw-rounded-full tw-border-0 tw-bg-[#f6f4fa] tw-text-lg tw-leading-none tw-text-[#5d556c] tw-transition hover:tw-bg-[#ece9f1]"
                  aria-label="Close"
                  onClick={() => setContactOpen(false)}
                >
                  ×
                </button>
              </div>
              <div className="tw-px-5 tw-py-4">
                <div className="tw-mb-4 tw-text-center">
                  {representativeModal.image && (
                    <Image
                      src={representativeModal.image.replace(
                        "tsgroup.s3.amazonaws.com",
                        "d2lpxiu1sq3srq.cloudfront.net"
                      )}
                      alt={representativeModal.name}
                      width={150}
                      height={150}
                      className="tw-mx-auto tw-h-[120px] tw-w-[120px] tw-rounded-full tw-object-cover"
                    />
                  )}
                  <h3 className="tw-font-display tw-mt-3 tw-text-lg tw-font-bold tw-text-[#14101c]">
                    {representativeModal.name}
                  </h3>
                  <p className="tw-mt-1 tw-flex tw-items-center tw-justify-center tw-gap-1.5 tw-text-sm tw-text-[#5d556c]">
                    <Image
                      src={
                        "/images/flags/4x3/" +
                        representativeModal.country?.code?.toLowerCase() +
                        ".svg"
                      }
                      alt=""
                      width={20}
                      height={20}
                    />{" "}
                    {representativeModal.country?.name || "Unknown Country"}
                  </p>
                </div>
                <ul className="tw-m-0 tw-space-y-0 tw-p-0">
                  {representativeModal.email && (
                    <li className="tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] tw-py-2.5 tw-text-sm tw-text-[#5d556c]">
                      <strong className="tw-text-[#14101c]">Email:</strong>{" "}
                      <a
                        href={`mailto:${representativeModal.email}`}
                        className="tw-text-[#854ec9] hover:tw-underline"
                      >
                        {representativeModal.email}
                      </a>
                    </li>
                  )}
                  {representativeModal.instagram_url && (
                    <li className="tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] tw-py-2.5 tw-text-sm tw-text-[#5d556c]">
                      <strong className="tw-text-[#14101c]">Instagram:</strong>{" "}
                      <a
                        href={representativeModal.instagram_url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="tw-break-all tw-text-[#854ec9] hover:tw-underline"
                      >
                        {representativeModal.instagram_url}
                      </a>
                    </li>
                  )}
                </ul>
                <button
                  type="button"
                  className="tw-mt-4 tw-w-full tw-cursor-pointer tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-py-2.5 tw-text-sm tw-font-semibold tw-text-white tw-transition hover:tw-bg-[#6a3da4]"
                  onClick={() => {
                    setContactOpen(false);
                    setInquiryOpen(true);
                  }}
                >
                  Ask a Question
                </button>
              </div>
            </div>
          </div>
        )}

        <InquiryModal
          representative={representativeModal}
          open={inquiryOpen}
          onClose={() => setInquiryOpen(false)}
        />
      </div>
    </main>
  );
}
